glosses=[('拾','pick up; gather'),('稿','draft; manuscript'),('躺','lie down'),('挪','move; shift'),('窄','narrow'),('折','fold'),('捏','hold between fingers; pinch'),('充电线','charging cable'),('杯印','cup ring'),('餐具','tableware'),('袖口','cuff'),('凶','fierce; harsh'),('伸','extend; reach'),('盘','plate; tray'),('姿','posture'),('洒','spill; sprinkle'),('泡','steep; soak'),('袖','sleeve'),('袖子','sleeve'),('杯沿','rim of a glass'),('玻璃','glass material'),('碎片','fragment'),('尴尬','awkward; embarrassed'),('责怪','blame'),('裁','cut; trim'),('截','section; cut off'),('剪','cut with scissors; edit'),('湿','wet'),('托盘','tray'),('挤','crowd; squeeze'),('挤到','crowd into'),('疏忽','oversight; neglect'),('线索','clue'),('严肃','serious'),('修正','correct; amend'),('闹事','cause trouble'),('恶意','malicious intent'),('见证人','witness'),('澄清','clarify'),('配','match; accompany'),('全程','entire process'),('草率','hasty'),('突','sudden'),('外','outside'),('渠','channel'),('传言','rumour'),('碎','broken; fragment'),('字幕','caption; subtitle')],
