turns=[('照片里你站着，是你碰倒的吗？','You are standing in the photo; did you knock it over?','Avoid inferring causation from posture',['不能从照片这样判断，我没有看到倒下以前那一下。']),('她说袖子碰到，你就亲眼看见了吧？','She says her sleeve caught it, so you witnessed it?','Attribute the account',['不是，那是她的说明，我当时低头。']),('不是热水，就完全没影响吧？','It wasn’t hot water, so no effect at all?','Retain the real inconvenience',['还是要等，也被声音吓了一下。']),('帮你解释，要不要写什么都没发生？','To explain for you, shall we write that nothing happened?','Correct only the added claim',['不要，杯子确实碎了，只是没有吵架的依据。'])],
usage=[('Attribute what you heard','据她的说明，是袖子碰到了杯子。','According to her, the sleeve caught the glass.','Name the source when you did not see the action.'),('Keep the limit of an image','照片没拍到前一刻，这一部分我不知道。','The photo misses the preceding moment; I don’t know that part.','An unknown part stays unknown.'),('Correct a specific claim','杯子确实碎了，但说我们吵架没有依据。','The glass did break, but there is no basis for saying we argued.','Do not erase real events to correct an interpretation.')],
